from app.models.entities import EventStatus
ERROR="error"
TRANSITIONS={EventStatus.CREATED:{EventStatus.CLASSIFIED,EventStatus.ERROR},EventStatus.CLASSIFIED:{EventStatus.PLANNING,EventStatus.ERROR},EventStatus.PLANNING:{EventStatus.POLICY_CHECK,EventStatus.ERROR},EventStatus.POLICY_CHECK:{EventStatus.AWAITING_APPROVAL,EventStatus.REJECTED,EventStatus.ERROR},EventStatus.AWAITING_APPROVAL:{EventStatus.APPROVED,EventStatus.REJECTED,EventStatus.ERROR},EventStatus.APPROVED:{EventStatus.EXECUTING,EventStatus.ERROR},EventStatus.EXECUTING:{EventStatus.MONITORING,EventStatus.ERROR},EventStatus.MONITORING:{EventStatus.COMPLETED,EventStatus.ERROR},EventStatus.COMPLETED:{EventStatus.ARCHIVED,EventStatus.ERROR},EventStatus.ARCHIVED:{EventStatus.ERROR},EventStatus.ERROR:set()}
def can_transition(current, target): return target in TRANSITIONS.get(current,set())
